import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

conv2d_source = r"""
#include <torch/extension.h>
#include <cuda.h>
#include <cuda_runtime.h>

#define TILE_W 16
#define TILE_H 16

__global__ void conv2d_kernel(
    const float* __restrict__ input, int N, int C_in, int H, int W,
    const float* __restrict__ weight, int C_out, int C_in_per_group, int K,
    const float* __restrict__ bias, bool has_bias,
    float* __restrict__ output, int H_out, int W_out,
    int stride, int padding, int dilation, int groups,
    int shared_h, int shared_w)
{
    extern __shared__ float smem[];

    int oc_per_group = C_out / groups;

    int b = blockIdx.z / C_out;
    int oc = blockIdx.z % C_out;
    int group = oc / oc_per_group;
    int ic_start = group * C_in_per_group;

    int tile_oh = blockIdx.y * TILE_H;
    int tile_ow = blockIdx.x * TILE_W;

    int in_h_start = tile_oh * stride - padding;
    int in_w_start = tile_ow * stride - padding;

    int tx = threadIdx.x;
    int ty = threadIdx.y;

    int oh = tile_oh + ty;
    int ow = tile_ow + tx;

    float sum = 0.0f;

    int num_elements = shared_h * shared_w;

    for (int icg = 0; icg < C_in_per_group; icg++) {
        int ic = ic_start + icg;

        for (int idx = ty * TILE_W + tx; idx < num_elements; idx += TILE_W * TILE_H) {
            int sh_row = idx / shared_w;
            int sh_col = idx % shared_w;
            int ih = in_h_start + sh_row;
            int iw = in_w_start + sh_col;
            float val = 0.0f;
            if (ih >= 0 && ih < H && iw >= 0 && iw < W) {
                val = input[((b * C_in + ic) * H + ih) * W + iw];
            }
            smem[idx] = val;
        }
        __syncthreads();

        if (oh < H_out && ow < W_out) {
            const float* w_ptr = weight + ((oc * C_in_per_group + icg) * K) * K;
            #pragma unroll
            for (int kh = 0; kh < K; kh++) {
                int sh_row = ty * stride + kh * dilation;
                const float* smem_row = smem + sh_row * shared_w + tx * stride;
                const float* w_row = w_ptr + kh * K;
                #pragma unroll
                for (int kw = 0; kw < K; kw++) {
                    sum += smem_row[kw * dilation] * w_row[kw];
                }
            }
        }
        __syncthreads();
    }

    if (oh < H_out && ow < W_out) {
        if (has_bias) {
            sum += bias[oc];
        }
        output[((b * C_out + oc) * H_out + oh) * W_out + ow] = sum;
    }
}

torch::Tensor conv2d_forward_cuda(
    torch::Tensor input,
    torch::Tensor weight,
    torch::Tensor bias,
    int stride,
    int padding,
    int dilation,
    int groups,
    bool has_bias)
{
    input = input.contiguous();
    weight = weight.contiguous();

    int N = input.size(0);
    int C_in = input.size(1);
    int H = input.size(2);
    int W = input.size(3);

    int C_out = weight.size(0);
    int C_in_per_group = weight.size(1);
    int K = weight.size(2);

    int H_out = (H + 2 * padding - dilation * (K - 1) - 1) / stride + 1;
    int W_out = (W + 2 * padding - dilation * (K - 1) - 1) / stride + 1;

    auto output = torch::empty({N, C_out, H_out, W_out}, input.options());

    int shared_h = (TILE_H - 1) * stride + (K - 1) * dilation + 1;
    int shared_w = (TILE_W - 1) * stride + (K - 1) * dilation + 1;

    dim3 block(TILE_W, TILE_H);
    dim3 grid(
        (W_out + TILE_W - 1) / TILE_W,
        (H_out + TILE_H - 1) / TILE_H,
        N * C_out
    );

    size_t shared_mem_size = shared_h * shared_w * sizeof(float);

    const float* bias_ptr = nullptr;
    if (has_bias) {
        bias = bias.contiguous();
        bias_ptr = bias.data_ptr<float>();
    }

    conv2d_kernel<<<grid, block, shared_mem_size>>>(
        input.data_ptr<float>(), N, C_in, H, W,
        weight.data_ptr<float>(), C_out, C_in_per_group, K,
        bias_ptr, has_bias,
        output.data_ptr<float>(), H_out, W_out,
        stride, padding, dilation, groups,
        shared_h, shared_w
    );

    return output;
}
"""

conv2d_cpp_source = r"""
torch::Tensor conv2d_forward_cuda(
    torch::Tensor input,
    torch::Tensor weight,
    torch::Tensor bias,
    int stride,
    int padding,
    int dilation,
    int groups,
    bool has_bias);
"""

conv2d_module = load_inline(
    name="custom_conv2d",
    cpp_sources=conv2d_cpp_source,
    cuda_sources=conv2d_source,
    functions=["conv2d_forward_cuda"],
    verbose=False,
)


class ModelNew(nn.Module):
    """
    Custom CUDA implementation of a standard 2D convolution with asymmetric
    input and a square kernel.
    """
    def __init__(self, in_channels: int, out_channels: int, kernel_size: int,
                 stride: int = 1, padding: int = 0, dilation: int = 1,
                 groups: int = 1, bias: bool = False):
        super(ModelNew, self).__init__()

        self.in_channels = in_channels
        self.out_channels = out_channels
        self.kernel_size = kernel_size
        self.stride = stride
        self.padding = padding
        self.dilation = dilation
        self.groups = groups
        self.has_bias = bias

        assert in_channels % groups == 0
        assert out_channels % groups == 0

        self.weight = nn.Parameter(
            torch.empty(out_channels, in_channels // groups, kernel_size, kernel_size)
        )

        if bias:
            self.bias = nn.Parameter(torch.empty(out_channels))
        else:
            self.register_parameter('bias', None)

        self.reset_parameters()

    def reset_parameters(self):
        nn.init.kaiming_uniform_(self.weight, a=5 ** 0.5)
        if self.bias is not None:
            fan_in = self.in_channels // self.groups * self.kernel_size * self.kernel_size
            bound = 1 / (fan_in ** 0.5) if fan_in > 0 else 0
            nn.init.uniform_(self.bias, -bound, bound)

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        x = x.cuda().contiguous()
        weight = self.weight.cuda()
        bias_tensor = self.bias.cuda() if self.bias is not None else torch.empty(0, device=x.device)

        return conv2d_module.conv2d_forward_cuda(
            x, weight, bias_tensor,
            self.stride, self.padding, self.dilation, self.groups,
            self.bias is not None
        )

